let _menhir_print_token : token -> string =
  fun _tok ->
    match _tok with
    | WILD ->
        "WILD"
    | VOID_TYPE ->
        "VOID_TYPE"
    | USE ->
        "USE"
    | UNKNOWN ->
        "UNKNOWN"
    | UNIT ->
        "UNIT"
    | UNDEF ->
        "UNDEF"
    | T_TYP ->
        "T_TYP"
    | TYP_FUN ->
        "TYP_FUN"
    | TYP_AP_SYMBOL ->
        "TYP_AP_SYMBOL"
    | TYP ->
        "TYP"
    | TURNSTILE ->
        "TURNSTILE"
    | TUPLE_EXTENSION ->
        "TUPLE_EXTENSION"
    | TRUE ->
        "TRUE"
    | TP_TPAT ->
        "TP_TPAT"
    | TIMES_FLOAT ->
        "TIMES_FLOAT"
    | TIMES ->
        "TIMES"
    | TILDE ->
        "TILDE"
    | THEN ->
        "THEN"
    | TEST ->
        "TEST"
    | STRING_TYPE ->
        "STRING_TYPE"
    | STRING_CONCAT ->
        "STRING_CONCAT"
    | STRING _ ->
        "STRING"
    | SLASH_TILDE ->
        "SLASH_TILDE"
    | SINT_TYPE ->
        "SINT_TYPE"
    | SINGLE_EQUAL ->
        "SINGLE_EQUAL"
    | SEMI_COLON ->
        "SEMI_COLON"
    | REC ->
        "REC"
    | QUOTED_LABEL _ ->
        "QUOTED_LABEL"
    | QUESTION ->
        "QUESTION"
    | P_PAT ->
        "P_PAT"
    | PROJECTOR_INVOKE _ ->
        "PROJECTOR_INVOKE"
    | POWER_FLOAT ->
        "POWER_FLOAT"
    | POWER ->
        "POWER"
    | POLY ->
        "POLY"
    | PLUS_FLOAT ->
        "PLUS_FLOAT"
    | PLUS ->
        "PLUS"
    | PIPELINE ->
        "PIPELINE"
    | PAUSE ->
        "PAUSE"
    | OPEN_TRIPLE_CURLY ->
        "OPEN_TRIPLE_CURLY"
    | OPEN_SQUARE_BRACKET ->
        "OPEN_SQUARE_BRACKET"
    | OPEN_PAREN ->
        "OPEN_PAREN"
    | OPEN_CURLY ->
        "OPEN_CURLY"
    | NOT_EQUAL_FLOAT ->
        "NOT_EQUAL_FLOAT"
    | NOT_EQUAL ->
        "NOT_EQUAL"
    | NAT_TYPE ->
        "NAT_TYPE"
    | NAMED_FUN ->
        "NAMED_FUN"
    | MOD_SEMI ->
        "MOD_SEMI"
    | MODULE ->
        "MODULE"
    | MINUS_FLOAT ->
        "MINUS_FLOAT"
    | MINUS ->
        "MINUS"
    | L_OR ->
        "L_OR"
    | L_NOT ->
        "L_NOT"
    | L_AND ->
        "L_AND"
    | LIVELIT_IDENT _ ->
        "LIVELIT_IDENT"
    | LET ->
        "LET"
    | LESS_THAN_FLOAT ->
        "LESS_THAN_FLOAT"
    | LESS_THAN_EQUAL_FLOAT ->
        "LESS_THAN_EQUAL_FLOAT"
    | LESS_THAN_EQUAL ->
        "LESS_THAN_EQUAL"
    | LESS_THAN ->
        "LESS_THAN"
    | INT_TYPE ->
        "INT_TYPE"
    | INTERNAL ->
        "INTERNAL"
    | INT _ ->
        "INT"
    | IN ->
        "IN"
    | IF ->
        "IF"
    | IDENT _ ->
        "IDENT"
    | HINT ->
        "HINT"
    | HIDE ->
        "HIDE"
    | GREATER_THAN_FLOAT ->
        "GREATER_THAN_FLOAT"
    | GREATER_THAN_EQUAL_FLOAT ->
